ROOT=Path(__file__).resolve().parent
BASE='''
:root{font-family:system-ui,"Microsoft YaHei",sans-serif;color:#1f2c36;background:#eef2f4;--ink:#1f2c36;--muted:#536875;--accent:#145f78;--line:#cbd6dc;--paper:#fff;--soft:#e7f0f4}*{box-sizing:border-box}body{margin:0}main{max-width:1240px;margin:auto;padding:32px clamp(18px,4vw,54px) 56px}h1{font-size:clamp(28px,4vw,48px);line-height:1.2;letter-spacing:-.035em;margin:16px 0}h2{font-size:23px;line-height:1.4;margin:0 0 14px}h3{font-size:17px;margin:0 0 8px}p{line-height:1.8}small,.muted{color:var(--muted)}small{font-size:12px}button,input,select,textarea{font:inherit}button,select,input,textarea{border:1px solid var(--line);border-radius:5px;background:var(--paper);color:var(--ink);padding:10px 13px}button{cursor:pointer;min-height:44px}button[aria-pressed=true],button.primary{background:var(--accent);color:white;border-color:var(--accent)}button:disabled{opacity:.48;cursor:not-allowed}:focus-visible{outline:3px solid #ba6800;outline-offset:3px}a{color:var(--accent);text-underline-offset:4px}.toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:20px 0}.paper{background:var(--paper);padding:24px;border:1px solid var(--line)}.twocol{display:grid;grid-template-columns:1fr 1fr;gap:24px}.eyebrow{text-transform:uppercase;font-size:12px;letter-spacing:.13em;color:var(--muted)}.pill{font-size:12px;background:var(--soft);padding:5px 8px;display:inline-block;line-height:1.5}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;text-align:left}th,td{padding:14px 12px;border-bottom:1px solid var(--line);vertical-align:top;line-height:1.6}th{color:var(--muted);font-size:13px}label{display:block;margin:10px 0;line-height:1.7}input[type=text],textarea{width:100%}textarea{min-height:100px}ol,ul{line-height:1.85;padding-left:22px}details{margin:18px 0;border-top:1px solid var(--line);padding-top:14px}summary{cursor:pointer;font-weight:600;line-height:1.8}.callout{border-left:4px solid var(--accent);padding:12px 18px;background:var(--soft);line-height:1.8}.big{font-size:48px;line-height:1.1;font-variant-numeric:tabular-nums;font-weight:700}.error{color:#9d2c1f}.good{color:#21613d}[hidden]{display:none!important}footer{border-top:1px solid var(--line);padding-top:20px;margin-top:40px;font-size:12px;line-height:1.8;color:var(--muted)}@media(max-width:720px){.twocol{grid-template-columns:1fr}main{padding-top:22px}.paper{padding:18px}th,td{padding:10px 8px}}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
'''
def emit(file,title,body,js='',css=''):
    (ROOT/file).write_text(f'<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><style>{BASE}{css}</style></head><body>{body}<script>{js}</script></body></html>',encoding='utf8')
def foot(skill,context):
    return f'<footer>{context}<br>本次按 <a href="https://github.com/plannotator/effective-html/blob/d95debbaef15af1d201fc6c10c77cf92b524a0d6/skills/{skill}/SKILL.md">{skill} 技能规则</a>制作的原创场景成果 · <a href="showcase.html" target="_top">返回场景展厅</a> · 上游 MIT；本页非上游官方样例。</footer>'

