emit('scenario-report.html','开源项目观察 · 决策简报', '''<main><div class="report-top"><span class="eyebrow">FIELD NOTES / 2026.09.07</span><span>研究决策简报 · 第 01 期</span></div><h1>哪些项目值得继续投入？</h1><p class="deck">五份现有研究记录，一次采用判断。先区分项目是什么，再看已经验证了什么，最后决定下一步。</p><section class="verdict"><div><span class="eyebrow">本轮判断</span><h2>优先试用可直接进入<br>研究交付的工作方法。</h2></div><div><p>Effective HTML 适合小范围试用；Agents 的约束可按需参考。其余项目保留为对应业务场景的资料入口。</p><small>判断来自本地研究笔记，不是项目质量排名，也不是性能测评。</small></div></section><div class="summary-strip"><div><span class="big">5</span><span>已收录研究对象</span></div><div><span class="big">2</span><span>有辅助程序或示例运行记录</span></div><div><span class="big">0</span><span>完成技能增益对照实验</span></div></div><section><div class="toolbar"><h2 style="margin:0;flex:1">证据与采用矩阵</h2><label for="filter" style="margin:0">范围 <select id="filter"><option value="all">全部项目</option><option value="rules">规则与技能</option><option value="tested">有运行记录</option></select></label></div><p class="muted" id="result-count" aria-live="polite">显示 5 个项目</p><div class="scroll"><table><thead><tr><th>项目 / 形态</th><th>可复用内容</th><th>验证深度</th><th>采用判断</th><th>查看依据</th></tr></thead><tbody id="research-rows"></tbody></table></div></section><section id="evidence" class="paper evidence" tabindex="-1" aria-live="polite"><span class="eyebrow">选中项目的依据</span><h2 id="e-name"></h2><div class="twocol"><div><h3>已核实</h3><p id="e-fact"></p><h3>适用工作</h3><p id="e-use"></p></div><div><h3>证据边界</h3><p id="e-limit"></p><a id="e-source" target="_blank" rel="noopener">查阅上游资料 ↗</a></div></div></section><section class="twocol" style="margin-top:32px"><div><h2>建议怎么用这份简报</h2><ol><li>先选与你当前任务相关的形态。</li><li>点“依据”确认研究深度。</li><li>有实际任务后再投入复现，记录返工与效果。</li></ol></div><div><h2>本轮仍然未知</h2><p>五个项目不能用同一个性能指标排名。辅助测试通过、演示可以运行、平台宣称支持某能力，分别回答不同问题。</p><p>下一轮最有价值的证据，是在同一任务中观察方法是否减少遗漏和返工。</p></div></section>'''+foot('html','数据来源：当前工作区 projects/001–005 的研究笔记，快照日期 2026-09-07。汇总数量按记录计算；后续在线变化未重新核验。')+'</main>',
'''const data='''+json.dumps(records,ensure_ascii=False)+''';function evidence(id,focus){const r=data.find(x=>x.id===id);document.getElementById('e-name').textContent=r.id+' / '+r.name;document.getElementById('e-fact').textContent=r.evidence;document.getElementById('e-use').textContent=r.use;document.getElementById('e-limit').textContent=r.limit;document.getElementById('e-source').href=r.source;if(focus)document.getElementById('evidence').focus()}function render(){const filter=document.getElementById('filter').value,rows=data.filter(r=>filter==='all'||(filter==='rules'&&r.kind==='规则与技能')||(filter==='tested'&&['001','005'].includes(r.id)));document.getElementById('research-rows').replaceChildren(...rows.map(r=>{const tr=document.createElement('tr');for(const text of [r.name+' / '+r.kind,r.learn,r.level,r.decision]){const td=document.createElement('td');td.textContent=text;tr.append(td)}const td=document.createElement('td'),b=document.createElement('button');b.textContent='依据';b.setAttribute('aria-label','查看 '+r.name+' 的依据');b.onclick=()=>evidence(r.id,true);td.append(b);tr.append(td);return tr}));document.getElementById('result-count').textContent='显示 '+rows.length+' 个项目';evidence(rows[0].id,false)}document.getElementById('filter').onchange=render;render();''',
'''.report-top{display:flex;justify-content:space-between;gap:20px;font-size:12px;border-bottom:2px solid var(--ink);padding-bottom:16px}.deck{font-size:18px;max-width:780px}.verdict{display:grid;grid-template-columns:1fr 1fr;gap:40px;background:#173e50;color:#fff;padding:32px;margin:32px 0}.verdict .eyebrow,.verdict small{color:#c4dce5}.verdict h2{font-size:29px;margin-top:14px}.summary-strip{display:grid;grid-template-columns:repeat(3,1fr);padding-bottom:26px;margin-bottom:30px;border-bottom:1px solid var(--line);gap:20px}.summary-strip>div{display:flex;align-items:center;gap:18px}.summary-strip>div>span:last-child{font-size:13px;max-width:130px}.evidence{margin-top:26px}#research-rows{font-size:14px}table{min-width:760px}.evidence h2{margin-top:12px}@media(max-width:720px){.verdict{grid-template-columns:1fr;gap:0;padding:24px}.summary-strip>div{display:block}.summary-strip>div>span{display:block}.summary-strip .big{font-size:36px}.report-top{flex-wrap:wrap}}''')

