emit('scenario-design.html','观潮 · 海岸观察手册', '''<div class="coast"><header><a href="#home" class="brand">观潮 <span>COASTAL FIELD GUIDE</span></a><nav><a href="#reading">读懂潮汐</a><a href="#field">观察手册</a><button id="night">夜间阅读</button></nav></header><main id="home"><div class="coast-hero"><div class="hero-copy"><span class="eyebrow">在海与陆之间，慢下来观察</span><h1>海岸，<br>每天写两遍。</h1><p>沿着潮水留下的线索，观察同一片海岸的变化。一份关于时间、水位与耐心的阅读手册。</p><a class="coast-link" href="#reading">开始阅读 <span>↓</span></a><small>原创科普专题视觉概念 · 非活动报名或潮汐预报</small></div><div class="tide-art"><svg viewBox="0 0 500 610" role="img" aria-labelledby="map-title"><title id="map-title">抽象海岸等高线，蓝色区域随示意水位改变</title><defs><pattern id="dots" width="24" height="24" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r="1" fill="currentColor" opacity=".2"/></pattern><clipPath id="shore"><path d="M0 0H500V610H0Z"/></clipPath></defs><rect width="500" height="610" fill="url(#dots)"/><g fill="none" stroke="currentColor" stroke-width="1" opacity=".36"><path d="M-80 530Q250 440 110 190T300-100"/><path d="M-60 560Q285 450 150 190T340-100"/><path d="M-40 590Q320 460 190 190T380-100"/><path d="M-20 620Q355 470 230 190T420-100"/><path d="M0 650Q390 480 270 190T460-100"/><path d="M20 680Q425 490 310 190T500-100"/><path d="M40 710Q460 500 350 190T540-100"/></g><g clip-path="url(#shore)"><path id="water" d="M0 400Q90 365 190 410T500 380V610H0Z" fill="#438899" opacity=".65"/></g><path d="M330 60V535M318 90H342M318 150H342M318 210H342M318 270H342M318 330H342M318 390H342M318 450H342M318 510H342" stroke="currentColor" fill="none"/><circle id="marker" cx="330" cy="400" r="8" fill="currentColor"/><text x="355" y="90" fill="currentColor" font-size="12">潮位刻度</text><text x="355" y="110" fill="currentColor" font-size="10">示意 · 非实测</text><text x="35" y="565" fill="currentColor" font-family="monospace" font-size="12">LAND / WATER / TIME</text></svg><div class="art-controls"><label for="tide">观察水位 <span id="tide-name">中潮位</span></label><input id="tide" type="range" min="0" max="100" value="50"><small>拖动观察海陆边界；刻度没有真实地理含义。</small></div></div></div><section id="reading" class="reading"><div><span class="eyebrow">01 / READ THE SHORE</span><h2>潮水退去，<br>变化才被看见。</h2></div><div><p>观察一片海岸，可以先从同一地点、不同时间的记录开始。水线的位置、裸露的地形、湿润的痕迹，帮助我们比较变化。</p><p>图中的曲线是视觉示意。它表达“水位变化会改变可见边界”，并不模拟真实地形、水动力或当地潮汐。</p></div></section><section id="field"><div class="field-heading"><h2>带着三个问题去观察</h2><span class="eyebrow">FIELD NOTES</span></div><div class="field-rows"><details><summary><span>A</span> 我站在哪里？</summary><p>记录固定观察点，以便让后续记录可比较。用远处不移动的地标帮助对齐视角。</p></details><details><summary><span>B</span> 这次与上次有什么不同？</summary><p>描述水线、颜色与裸露区域；把直接看到的现象和自己的解释分开。</p></details><details><summary><span>C</span> 还有什么不能从一张图判断？</summary><p>一张图不能证明完整周期，也不能替代当地潮汐、天气和现场安全信息。</p></details></div></section>'''+foot('design-artifact','视觉选择：海岸等高线作为主视觉，宋体标题与系统正文分工，蓝绿与浅砂色对应水陆，水位交互服务主题。插图为代码绘制的抽象示意。')+'''</main></div>''',
'''const root=document.documentElement;document.getElementById('night').onclick=e=>{const night=root.dataset.theme==='night'||(!root.dataset.theme&&matchMedia('(prefers-color-scheme:dark)').matches);root.dataset.theme=night?'day':'night';e.currentTarget.textContent=night?'夜间阅读':'日间阅读'};document.getElementById('tide').oninput=e=>{const v=Number(e.target.value),y=520-v*3.5;document.getElementById('water').setAttribute('d',`M0 ${y}Q90 ${y-35} 190 ${y+10}T500 ${y-20}V610H0Z`);document.getElementById('marker').setAttribute('cy',y);document.getElementById('tide-name').textContent=v<30?'低潮位':v>70?'高潮位':'中潮位'};''',
''':root{--sand:#e9e4d7;--coast-ink:#143f43;--coast-muted:#46656a;--coast-line:#9baea9;--coast-blue:#236773;background:var(--sand);color:var(--coast-ink)}.coast{background:var(--sand);color:var(--coast-ink);min-height:100vh}.coast a{color:var(--coast-ink)}.coast header{max-width:1360px;margin:auto;padding:25px 40px;display:flex;justify-content:space-between;gap:20px;border-bottom:1px solid var(--coast-line)}.brand{text-decoration:none;font-family:SimSun,serif;font-size:27px}.brand span{font:10px system-ui;letter-spacing:.12em;margin-left:12px}.coast nav{display:flex;align-items:center;gap:22px;font-size:13px}.coast nav button{background:transparent;border-color:var(--coast-line);color:var(--coast-ink)}.coast main{max-width:1360px}.coast-hero{display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:center}.hero-copy h1{font-family:SimSun,Georgia,serif;font-weight:500;font-size:clamp(50px,7vw,94px);line-height:1.18;letter-spacing:-.03em;margin:36px 0}.hero-copy p{max-width:360px;line-height:2}.coast .eyebrow,.coast small{color:var(--coast-muted)}.hero-copy small{display:block;margin-top:40px}.coast-link{display:flex;justify-content:space-between;max-width:220px;padding:15px 0;border-bottom:1px solid var(--coast-ink);text-decoration:none}.tide-art{border-left:1px solid var(--coast-line);padding-left:24px}.tide-art svg{display:block;width:100%;max-height:570px}.art-controls label{display:flex;justify-content:space-between}.art-controls input{display:block;width:100%;accent-color:var(--coast-blue);padding:0}.reading{display:grid;grid-template-columns:1fr 1fr;gap:60px;border-top:1px solid var(--coast-line);margin-top:70px;padding:50px 0}.reading h2{font-family:SimSun,serif;font-size:clamp(28px,4vw,42px);font-weight:500;margin-top:20px;line-height:1.5}.field-heading{display:flex;justify-content:space-between;align-items:center;gap:20px}.field-rows summary{display:flex;gap:40px;font-size:22px;font-weight:400}.field-rows summary span{font-family:Georgia,serif}.coast details,.coast footer{border-color:var(--coast-line);color:var(--coast-muted)}@media(prefers-color-scheme:dark){:root{--sand:#102f34;--coast-ink:#e1e8db;--coast-muted:#bdcec8;--coast-line:#56726f;--coast-blue:#8ec4c7}}:root[data-theme=night]{--sand:#102f34;--coast-ink:#e1e8db;--coast-muted:#bdcec8;--coast-line:#56726f;--coast-blue:#8ec4c7}:root[data-theme=day]{--sand:#e9e4d7;--coast-ink:#143f43;--coast-muted:#46656a;--coast-line:#9baea9;--coast-blue:#236773}@media(max-width:720px){.coast header{padding:18px;flex-wrap:wrap}.coast nav{gap:15px}.coast-hero,.reading{grid-template-columns:1fr;gap:26px}.hero-copy h1{font-size:48px}.tide-art{border-left:0;border-top:1px solid var(--coast-line);padding:20px 0}.tide-art svg{max-height:420px}.reading{margin-top:38px;padding-top:30px}.field-heading{display:block}.brand span{font-size:9px}}''')

