emit('scenario-wireframe.html','客服工作台 · 三种结构评审', '''<main><span class="eyebrow">STRUCTURE REVIEW / 低保真 · 虚构工单</span><h1>客服怎样找到下一件该处理的事？</h1><p>同样三条工单，比较队列工作台、分流看板和逐件处理。当前只审阅信息层级、导航和任务顺序。</p><div class="toolbar"><button data-layout="split" aria-pressed="true">队列 + 详情</button><button data-layout="board" aria-pressed="false">优先级看板</button><button data-layout="guided" aria-pressed="false">逐件处理</button></div><p id="layout-note" class="callout"></p><section id="workspace"></section><section class="paper review"><h2>这次评审要决定什么</h2><div class="twocol"><div><h3>必须同时知道</h3><ul><li>哪个客户遇到什么问题。</li><li>优先级与已等待时间。</li><li>下一步是核对、复现还是记录需求。</li></ul></div><div><h3>留到后续原型</h3><ul><li>真实分派、回复与状态保存。</li><li>服务等级计算与团队权限。</li><li>品牌色、组件细节与动效。</li></ul></div></div></section>'''+foot('html-wireframe','输入：三条虚构工单，信息在三种结构中保持一致。操作仅用于切换和审阅；不会回复客户或修改真实工单。')+'</main>',
'''const tickets='''+json.dumps(tickets,ensure_ascii=False)+''';let layout='split',selected=0;function render(){document.querySelectorAll('[data-layout]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.layout===layout)));document.getElementById('layout-note').textContent={split:'队列 + 详情：便于快速切换上下文；需要在列表密度与阅读空间之间取舍。',board:'优先级看板：便于比较负载与分流；单条工单的完整上下文需要展开。',guided:'逐件处理：明确下一步，减少跳转；跨工单比较与插入处理的灵活性较低。'}[layout];const host=document.getElementById('workspace');host.replaceChildren();const detail=t=>`<span class="pill">${t.id} / ${t.priority}优先级 / ${t.age}</span><h2>${t.title}</h2><p>客户：${t.customer}</p><p>${t.detail}</p><div class="next-action"><strong>建议下一步</strong><p>${t.next}</p></div>`;if(layout==='split'){host.className='split';const queue=document.createElement('div');queue.className='queue';queue.innerHTML='<h3>待处理队列 · 3</h3>';tickets.forEach((t,i)=>{const b=document.createElement('button');b.innerHTML=`<strong>${t.id} · ${t.title}</strong><small>${t.customer} / ${t.priority} / ${t.age}</small>`;b.setAttribute('aria-pressed',String(i===selected));b.onclick=()=>{selected=i;render()};queue.append(b)});const pane=document.createElement('article');pane.className='paper';pane.innerHTML=detail(tickets[selected]);host.append(queue,pane)}else if(layout==='board'){host.className='board';tickets.forEach(t=>{const col=document.createElement('section');col.className='paper';col.innerHTML=`<h3>${t.priority}优先级 · 1</h3><h2>${t.title}</h2><p>${t.customer} / ${t.age}</p><details><summary>查看处理依据</summary><p>${t.detail}</p><strong>${t.next}</strong></details>`;host.append(col)})}else{host.className='paper';host.innerHTML=`<p>当前 ${selected+1} / 3 · 按优先级审阅</p>${detail(tickets[selected])}<div class="toolbar"><button id="back-ticket" ${selected===0?'disabled':''}>上一条</button><button id="next-ticket" ${selected===2?'disabled':''}>下一条</button></div>`;document.getElementById('back-ticket').onclick=()=>{selected--;render()};document.getElementById('next-ticket').onclick=()=>{selected++;render()}}}document.querySelectorAll('[data-layout]').forEach(b=>b.onclick=()=>{layout=b.dataset.layout;render()});render();''',
''':root{--ink:#252525;--muted:#555;--accent:#444;--line:#aaa;--soft:#eee;background:#f7f7f7}.split{display:grid;grid-template-columns:330px 1fr;gap:20px}.queue{border:1px solid #aaa;padding:18px;background:#fff}.queue button{display:block;width:100%;text-align:left;margin-top:12px}.queue small{display:block;margin-top:12px}.queue button[aria-pressed=true] small{color:white}.board{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.board h2{font-size:20px;margin-top:28px}#workspace h2{margin-top:20px}.next-action{border-top:1px solid #aaa;margin-top:28px;padding-top:20px}.review{margin-top:30px}@media(max-width:850px){.split{grid-template-columns:1fr}.board{grid-template-columns:1fr}}''')

# 4. Complete editorial review flow, with recoverable failure and explicit boundary.
emit('scenario-prototype.html','内容审阅台 · 发布前审核', '''<main><div class="appbar"><strong>FIELDNOTES / 内容审阅台</strong><span class="pill">交互原型 · 本地模拟</span></div><div class="toolbar"><span class="eyebrow">ISSUE 07 / 待审稿件</span><button id="reset" style="margin-left:auto">重置演示</button></div><div class="review-app"><aside class="article-list"><h3>本次待审 · 1 篇</h3><p><strong>把研究结论变成<br>可验证的成果</strong></p><span class="pill" id="list-state">待审核</span><p class="muted">作者：林岚（虚构）<br>版本：v3<br>最后修改：示例时间 14:20</p><hr><h3>审核记录</h3><ol id="history"><li>作者提交 v3，等待审阅。</li></ol></aside><article class="article-preview"><span class="eyebrow">文章预览</span><h1>把研究结论变成<br>可验证的成果</h1><p class="standfirst">一份可操作的原型，可以让讨论从“看起来不错”转向“这个流程是否成立”。</p><h2>先问一个明确的问题</h2><p>在制作页面前，确定读者需要判断什么。结构没有确认，就先比较布局；行为存在疑问，就模拟关键状态。</p><blockquote>有来源的结论、可触发的状态、可复核的结果，是本次稿件的三个检查点。</blockquote><h2>再决定交付深度</h2><p>原型可以验证表单、反馈与恢复路径。真实认证、权限和数据写入仍由正式系统承担。</p><p><a href="https://github.com/plannotator/effective-html">文中引用：Effective HTML</a></p><details><summary>查看稿件元信息</summary><p>受众：项目研究者。分类：工作方法。所有作者、审核记录与流程状态均为示例数据。</p></details></article><aside class="approval"><span class="eyebrow">审核决策</span><h2 id="decision">完成检查后可通过</h2><p id="gate" aria-live="polite">已核对 0 / 3 项</p><label><input class="check" type="checkbox"> 结论与来源一致</label><label><input class="check" type="checkbox"> 没有未证实的效果承诺</label><label><input class="check" type="checkbox"> 标题与正文表达一致</label><div class="approval-actions"><button class="primary" id="approve" disabled>通过审核</button><button id="return">退回修改</button><button id="publish" disabled>提交发布请求</button></div><p id="status" role="status" class="muted">完成三项检查，或填写原因退回。</p><details><summary>模拟条件</summary><label><input id="fail" type="checkbox"> 下一次审核保存失败</label></details><small>此页不会发布文章或发送通知；刷新不会保留记录。</small></aside></div><dialog id="return-dialog" aria-labelledby="return-title"><form id="return-form"><h2 id="return-title">退回作者修改</h2><p>给出具体位置与需要修改的内容。</p><label for="reason">退回原因（至少 6 个字）</label><textarea id="reason" required minlength="6" aria-describedby="reason-help"></textarea><p id="reason-help" class="muted">示例：第二段需要补充实际验证的范围。</p><div class="toolbar"><button type="button" id="cancel">取消</button><button type="submit" class="primary">确认退回</button></div></form></dialog><dialog id="boundary" aria-labelledby="boundary-title"><h2 id="boundary-title">到达正式发布的边界</h2><p>真实系统将在这里检查发布权限、最新版本、审核记录，并调用发布服务。本原型没有执行这些操作。</p><button id="close-boundary" class="primary">返回稿件</button></dialog>'''+foot('html-prototype','输入：一篇虚构待审稿。覆盖待审、检查不足、保存中、保存失败与重试、审核通过、退回修改和发布边界。无远程写入。')+'</main>',
'''const checks=[...document.querySelectorAll('.check')],approve=document.getElementById('approve'),publish=document.getElementById('publish'),ret=document.getElementById('return'),status=document.getElementById('status'),dialog=document.getElementById('return-dialog');let state='pending',busy=false;function sync(){const n=checks.filter(c=>c.checked).length;document.getElementById('gate').textContent='已核对 '+n+' / 3 项';approve.disabled=busy||n<3||state==='approved'||state==='returned';publish.disabled=busy||state!=='approved';ret.disabled=busy||state==='returned';checks.forEach(c=>c.disabled=busy||state==='returned');document.getElementById('fail').disabled=busy;document.getElementById('reset').disabled=busy}checks.forEach(c=>c.onchange=()=>{if(state==='approved'){state='pending';approve.textContent='通过审核';status.className='muted';document.getElementById('list-state').textContent='待审核';document.getElementById('decision').textContent='检查发生变化，请重新审核';status.textContent='原审核状态已撤销，发布请求重新禁用。'}sync()});function log(text){const li=document.createElement('li');li.textContent=text;document.getElementById('history').append(li)}approve.onclick=()=>{busy=true;sync();approve.textContent='正在保存…';status.textContent='正在保存模拟审核记录…';const fail=document.getElementById('fail').checked;setTimeout(()=>{busy=false;if(fail){document.getElementById('fail').checked=false;status.textContent='模拟保存失败。检查结果已保留，请重试审核。';status.className='error';approve.textContent='重试审核';log('审核保存失败，等待重试。')}else{state='approved';approve.textContent='已通过审核';document.getElementById('list-state').textContent='已通过';document.getElementById('decision').textContent='可以提交发布请求';status.textContent='审核记录已保存在本页。';status.className='good';log('三项检查通过，审核通过。')}sync()},700)};ret.onclick=()=>{dialog.showModal();document.getElementById('reason').focus()};function closeReturn(){dialog.close();ret.focus()}document.getElementById('cancel').onclick=closeReturn;dialog.addEventListener('cancel',()=>{setTimeout(()=>ret.focus(),0)});document.getElementById('return-form').onsubmit=e=>{e.preventDefault();const input=document.getElementById('reason');if(input.value.trim().length<6){input.setCustomValidity('请填写至少 6 个字的具体原因。');input.reportValidity();return}state='returned';document.getElementById('list-state').textContent='待修改';document.getElementById('decision').textContent='已退回作者';status.textContent='退回原因：'+input.value.trim();log('退回修改：'+input.value.trim());dialog.close();sync();document.getElementById('reset').focus()};document.getElementById('reason').oninput=e=>e.target.setCustomValidity('');publish.onclick=()=>{document.getElementById('boundary').showModal()};document.getElementById('close-boundary').onclick=()=>{document.getElementById('boundary').close();publish.focus()};document.querySelectorAll('dialog').forEach(d=>d.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const controls=[...d.querySelectorAll('button:not([disabled]),textarea:not([disabled]),input:not([disabled]),select:not([disabled]),a[href]')];const first=controls[0],last=controls[controls.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}));document.getElementById('boundary').addEventListener('cancel',()=>setTimeout(()=>publish.focus(),0));document.getElementById('reset').onclick=()=>location.reload();sync();''',
'''main{max-width:1520px}.appbar{display:flex;align-items:center;justify-content:space-between;gap:20px;border-bottom:1px solid var(--line);padding-bottom:20px}.review-app{display:grid;grid-template-columns:220px minmax(0,1fr) 290px;gap:0;border:1px solid var(--line);background:white}.article-list{padding:22px;background:#edf2f5;border-right:1px solid var(--line)}.article-list p{font-size:14px}.article-list li{font-size:12px;margin-bottom:10px}.article-preview{padding:36px}.article-preview h1{font-family:SimSun,Georgia,serif;font-size:35px;line-height:1.45}.article-preview h2{font-size:19px;margin-top:32px}.standfirst{font-size:18px;color:var(--muted)}blockquote{margin:24px 0;padding:20px;border-left:3px solid #397386;background:#edf4f5;line-height:1.8}.approval{padding:24px;border-left:1px solid var(--line);background:#f8fafb}.approval h2{margin-top:18px;font-size:24px}.approval label{font-size:14px;margin:18px 0}.approval-actions{display:grid;gap:10px;margin-top:26px}.approval #status{font-size:13px;min-height:60px}dialog{max-width:540px;width:calc(100% - 32px);padding:28px;border:1px solid var(--line);border-radius:8px;color:var(--ink)}dialog::backdrop{background:#11273499}@media(max-width:1080px){.review-app{grid-template-columns:1fr 290px}.article-list{grid-column:1/-1;border-right:0;border-bottom:1px solid var(--line)}.article-list p,.article-list ol{display:inline-block;vertical-align:top;margin-right:24px}.article-list hr{display:none}}@media(max-width:720px){.review-app{grid-template-columns:1fr}.article-preview{padding:22px}.article-preview h1{font-size:30px}.approval{border-left:0;border-top:1px solid var(--line)}.appbar{flex-wrap:wrap}}''')

# 5. Source-preserving migration plan with real dependency questions and decision gates.
steps=[
dict(id='S1',title='盘点与冻结范围',role='内容负责人',when='切换前',dep='无前置',output='迁移清单、负责人、旧链接与权限映射',gate='范围由内容负责人确认' ,source='R1'),
dict(id='S2',title='试迁与核对',role='工程负责人 + 内容负责人',when='正式迁移前',dep='S1',output='试迁结果、失败清单、链接与附件核对',gate='抽样规则和数量尚待确认，不能自行写成通过',source='R2'),
dict(id='S3',title='备份与回退准备',role='工程负责人',when='切换前',dep='S1',output='完整备份、恢复步骤、旧库只读访问',gate='完成恢复验证后才允许切换',source='R3'),
dict(id='S4',title='只读窗口与正式迁移',role='工程负责人',when='切换窗口内',dep='S2 + S3',output='最终导入结果与错误记录',gate='窗口日期待确认；有阻断错误则停止切换',source='R4'),
dict(id='S5',title='切换后的验收',role='内容负责人 + 业务代表',when='切换后',dep='S4',output='检索、权限、附件和链接验收记录',gate='关键访问失败则启动回退评估',source='R5'),
dict(id='S6',title='观察与旧库退出',role='内容负责人 + 工程负责人',when='观察期结束后',dep='S5',output='遗留问题清单与旧库退出决策',gate='观察期长度待确认，旧库不自动删除',source='R6')]
source_text=['R1：先盘点待迁移的知识库内容，记录负责人、旧链接与权限；范围由内容负责人确认。','R2：正式迁移前先做试迁，由工程与内容负责人核对附件、链接和失败记录；抽样标准另行确认。','R3：切换前完成完整备份和恢复验证，旧库保留只读访问。','R4：试迁和回退准备都通过后，工程负责人在约定只读窗口执行正式迁移；窗口日期待定，阻断错误出现时停止切换。','R5：切换后由内容负责人和业务代表验收检索、权限、附件和链接；关键访问失败时评估回退。','R6：观察期结束并确认遗留问题后再讨论旧库退出；观察期长度待定，不自动删除旧库。']
emit('scenario-plan.html','知识库迁移 · 实施评审稿', '''<main><div class="eyebrow">IMPLEMENTATION PLAN / 方案评审 · 示例委托</div><h1>知识库迁移：<br>先验证可回退，再决定切换。</h1><p>本方案将六条示例委托整理为可审阅的执行顺序。日期、人名、观察期和抽样标准没有给定，因此保留为未决事项。</p><div class="plan-summary"><div><span class="eyebrow">切换条件</span><h2>试迁核对通过<br>＋ 恢复验证完成</h2></div><div><span class="eyebrow">停止条件</span><h2>阻断错误出现<br>→ 停止切换</h2></div><div><span class="eyebrow">退出边界</span><h2>观察期后另行决定<br>旧库不自动删除</h2></div></div><div class="toolbar"><button id="full" aria-pressed="true">全部阶段</button><button id="gates" aria-pressed="false">只看切换前置条件</button><a href="#questions">查看未决事项 ↓</a><a href="#source">核对原始委托 ↓</a></div><div class="plan-layout"><div id="phases"></div><aside class="paper sticky"><span class="eyebrow">DEPENDENCIES</span><h2>依赖关系</h2><p>S1 范围确认</p><div class="fork"><span>↓ S2 试迁</span><span>↓ S3 回退准备</span></div><p class="merge">共同完成 ↓</p><p>S4 正式迁移<br>↓<br>S5 验收<br>↓<br>S6 退出决策</p><small>分支来自 R4 的两个前置条件，不代表已排定并行资源。</small></aside></div><section id="questions" class="paper" style="margin-top:28px"><h2>需要决策的事项</h2><div class="scroll"><table><thead><tr><th>问题</th><th>影响</th><th>对应来源</th></tr></thead><tbody><tr><td>试迁的抽样标准是什么？</td><td>决定如何判断试迁通过</td><td>R2</td></tr><tr><td>只读窗口是哪一天、持续多久？</td><td>决定正式迁移安排</td><td>R4</td></tr><tr><td>观察期长度与退出决策由谁最终确认？</td><td>决定旧库保留与退出流程</td><td>R6；最终决策人未指定</td></tr></tbody></table></div></section><section id="source" class="paper" style="margin-top:28px"><h2>原始委托 · 本演示的事实边界</h2><p>以下为制作场景时给定的虚构委托，不代表用户已接受的真实迁移安排。</p>'''+''.join(f'<p id="R{i+1}">{x}</p>' for i,x in enumerate(source_text))+'''</section>'''+foot('html-plan','结构解释：将原文分为六阶段，并依据 R4 标出 S2/S3 汇合；没有添加实际进度、截止日或已通过状态。')+'</main>',
'''const phases='''+json.dumps(steps,ensure_ascii=False)+''';function render(gates){document.getElementById('full').setAttribute('aria-pressed',String(!gates));document.getElementById('gates').setAttribute('aria-pressed',String(gates));document.getElementById('phases').innerHTML=phases.filter(s=>!gates||['S1','S2','S3'].includes(s.id)).map(s=>`<article class="phase"><div class="phase-number">${s.id}</div><div><span class="eyebrow">${s.when} / 依赖 ${s.dep}</span><h2>${s.title}</h2><p><strong>责任角色：</strong>${s.role}</p><p><strong>交付：</strong>${s.output}</p><p class="callout">${s.gate}</p><a href="#${s.source}">核对来源 ${s.source} ↓</a></div></article>`).join('')}document.getElementById('full').onclick=()=>render(false);document.getElementById('gates').onclick=()=>render(true);render(false);''',
'''#questions table{min-width:600px}.plan-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:0;background:#1f3541;color:#fff;padding:26px;margin:30px 0}.plan-summary>div{padding:0 20px;border-right:1px solid #5f747e}.plan-summary>div:last-child{border:0}.plan-summary .eyebrow{color:#bcd0da}.plan-summary h2{font-size:21px;margin:16px 0 0}.plan-layout{display:grid;grid-template-columns:minmax(0,1fr) 270px;gap:26px}.phase{display:grid;grid-template-columns:58px 1fr;gap:14px;padding:28px 0;border-top:1px solid var(--line)}.phase-number{font:24px Georgia,serif;color:var(--muted)}.phase h2{margin-top:9px}.phase p{margin:10px 0}.sticky{align-self:start;position:sticky;top:20px}.sticky h2{margin-top:12px}.fork{display:flex;justify-content:space-between;gap:10px}.fork span{font-size:13px;background:var(--soft);padding:8px}.merge{font-size:12px;text-align:center}@media(max-width:850px){.plan-layout{grid-template-columns:1fr}.sticky{position:static;grid-row:1}.plan-summary{grid-template-columns:1fr;gap:24px}.plan-summary>div{border-right:0;border-bottom:1px solid #5f747e;padding:0 0 20px}}''')

# 6. Request trace across a system, with failures and recovery, not a generic icon chain.
paths={
'ok':dict(label='正常处理',steps=[('browser','用户选择图片','浏览器显示本地预览；文件还没有处理完成。','待上传'),('api','请求上传凭据','API 检查文件类型与大小，返回本次上传地址。','校验通过'),('store','文件进入对象存储','浏览器上传原文件；上传成功不等于缩略图已生成。','原图已保存'),('queue','创建处理任务','API 记录任务并交给队列，返回任务编号。','排队中'),('worker','生成缩略图','工作进程读取原图，生成派生文件并写回存储。','处理中'),('browser','界面显示完成','任务状态更新为完成，界面读取结果并展示缩略图。','完成')]),
'invalid':dict(label='文件校验失败',steps=[('browser','用户选择超限文件','此路径使用虚构的超限条件，未读取真实文件。','待上传'),('api','API 拒绝请求','校验未通过，返回可理解的错误原因，不签发上传地址。','被拒绝'),('browser','用户重新选择文件','显示“文件超过此示例允许范围”，允许重新选择。对象存储和队列未参与。','可重新选择')]),
'retry':dict(label='处理失败后重试',steps=[('browser','用户选择图片','开始正常上传路径。','待上传'),('api','请求通过校验','返回上传地址和关联标识。','校验通过'),('store','保存原图','原图保存成功，后续处理失败时仍可复用。','原图已保存'),('queue','任务等待处理','创建带有任务编号的处理请求。','排队中'),('worker','处理发生暂时错误','示例：工作进程暂时无法读取原图。任务记录错误，不能提前显示成功。','处理失败'),('queue','按原任务重试','调度重试同一任务；真实系统需保证重复执行不会产生错误副作用。','重试中'),('worker','重试完成','重新读取原图，成功生成派生文件。','处理完成'),('browser','用户看到最终结果','界面从处理中或可重试状态更新为完成。','完成')])}
nodes=[('browser','用户设备','选择、预览、结果'),('api','应用 API','校验、任务状态'),('store','对象存储','原图与派生文件'),('queue','任务队列','排队与重试'),('worker','处理进程','生成缩略图')]
emit('scenario-diagram.html','图片处理系统 · 可交互请求追踪', '''<main><div class="eyebrow">SYSTEM EXPLAINER / 架构教学场景</div><h1>上传成功，为什么还没看到缩略图？</h1><p>沿着一张图片的处理路径，区分上传、排队、后台处理和结果展示。切换异常路径，观察哪些组件实际参与。</p><div class="toolbar"><label for="path" style="margin:0">请求路径 <select id="path"><option value="ok">正常处理</option><option value="invalid">文件校验失败</option><option value="retry">处理失败后重试</option></select></label><button id="back">上一步</button><button id="forward" class="primary">下一步</button><button id="restart">从头查看</button><span id="step-counter" aria-live="polite"></span></div><section class="system"><div class="boundary-label">组件分工 · 节点固定，蓝色表示当前参与方</div><div class="architecture-scroll"><svg class="architecture" viewBox="0 0 1000 330" role="img" aria-labelledby="arch-title arch-desc"><title id="arch-title">图片上传与后台处理的连接关系</title><desc id="arch-desc">用户向 API 申请上传并查询状态，向对象存储上传原图。API 创建队列任务，工作进程消费任务并读写对象存储。</desc><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto-start-reverse"><path d="M0 0L8 4L0 8Z" fill="#aacbd8"/></marker></defs><rect x="220" y="15" width="755" height="295" rx="10" fill="none" stroke="#688995" stroke-dasharray="5 5"/><text x="240" y="39" fill="#c1d6df" font-size="12">服务端 · 任务状态存储简化并入 API</text><g fill="none" stroke="#aacbd8" stroke-width="2" marker-end="url(#arrow)"><path d="M180 102H270"/><path d="M420 102H525"/><path d="M675 102H780"/><path d="M105 140V244H445"/><path d="M855 140V244H625"/></g><g fill="#d3e4eb" font-size="12"><text x="190" y="86">申请 / 查询</text><text x="433" y="85">创建任务</text><text x="690" y="85">消费任务</text><text x="200" y="231">上传原图</text><text x="704" y="231">读取 / 写回</text></g><g fill="#285061" stroke="#799ca9"><rect x="30" y="65" width="150" height="75" rx="6"/><rect x="270" y="65" width="150" height="75" rx="6"/><rect x="525" y="65" width="150" height="75" rx="3"/><rect x="780" y="65" width="150" height="75" rx="6"/><path d="M445 215C445 190 625 190 625 215V272C625 297 445 297 445 272Z"/><ellipse cx="535" cy="215" rx="90" ry="18"/></g><g fill="#fff" text-anchor="middle" font-size="17"><text x="105" y="110">用户设备</text><text x="345" y="110">应用 API</text><text x="600" y="110">任务队列</text><text x="855" y="110">处理进程</text><text x="535" y="261">对象存储</text></g></svg></div><div class="nodes">'''+''.join(f'<button class="node" data-node="{key}"><span class="node-code">{i+1:02d}</span><strong>{label}</strong><small>{desc}</small></button>' for i,(key,label,desc) in enumerate(nodes))+'''</div><div class="relationship"><span>浏览器 ↔ API：申请与查询</span><span>浏览器 → 存储：上传原图</span><span>API → 队列 → 处理进程</span><span>处理进程 ↔ 存储：读取与写回</span></div></section><div class="trace-layout"><section class="paper current" aria-live="polite"><span id="state" class="pill"></span><h2 id="event-title"></h2><p id="event-copy"></p><div id="inspect" class="callout" hidden></div></section><section class="paper"><h2>本条路径的事件记录</h2><ol id="trace"></ol></section></div><section class="twocol" style="margin-top:28px"><div><h2>系统里有三种“成功”</h2><p><strong>上传成功：</strong>原文件已保存。<br><strong>处理成功：</strong>派生文件生成完毕。<br><strong>用户可见：</strong>界面拿到最新状态和结果。</p></div><div><h2>本图的简化边界</h2><p>这是教学用系统设计，未连接任何真实服务。任务状态存储并入 API；未展开鉴权、恶意文件检测、重试上限与事件投递细节。连线语义以文字关系和事件记录为准。</p></div></section>'''+foot('html-diagram','选择“系统分工 + 请求序列”组合表达；三条路径为给定教学场景，不是 Effective HTML 仓库的内部实现。支持逐步和节点解释，无自动动画。')+'</main>',
'''const paths='''+json.dumps(paths,ensure_ascii=False)+''',roles={browser:'用户设备负责选择文件、发起上传和展示结果；它不负责后台缩略图计算。',api:'应用 API 负责请求校验、创建任务和暴露状态；本示意图把状态存储并入这一节点。',store:'对象存储保留原图与派生文件。文件存在不能证明所有处理任务都已完成。',queue:'队列隔开请求响应与耗时处理，并为重试提供调度位置。具体交付语义由真实实现决定。',worker:'处理进程执行耗时转换，完成或失败后更新任务结果。'};let step=0;function render(){const flow=paths[document.getElementById('path').value].steps,e=flow[step];document.querySelectorAll('[data-node]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.node===e[0])));document.getElementById('step-counter').textContent=(step+1)+' / '+flow.length;document.getElementById('state').textContent=e[3];document.getElementById('event-title').textContent=e[1];document.getElementById('event-copy').textContent=e[2];document.getElementById('back').disabled=step===0;document.getElementById('forward').disabled=step===flow.length-1;document.getElementById('inspect').hidden=true;document.getElementById('trace').innerHTML=flow.map((e,i)=>`<li class="${i===step?'now':i<step?'done':''}"><button data-event="${i}" aria-current="${i===step?'step':'false'}">${e[1]} <small>${i<step?'已查看':i===step?'当前':'待查看'}</small></button></li>`).join('');document.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>{step=Number(b.dataset.event);render()})}document.getElementById('path').onchange=()=>{step=0;render()};document.getElementById('back').onclick=()=>{step--;render()};document.getElementById('forward').onclick=()=>{step++;render()};document.getElementById('restart').onclick=()=>{step=0;render()};document.querySelectorAll('[data-node]').forEach(b=>b.onclick=()=>{const p=document.getElementById('inspect');p.hidden=false;p.textContent=roles[b.dataset.node]});render();''',
'''.architecture-scroll{overflow-x:auto;margin-bottom:22px}.architecture{display:block;width:100%;min-width:700px}.system{border:1px solid #476575;background:#183644;color:white;padding:26px}.boundary-label{font-size:12px;color:#c1d6df;letter-spacing:.08em;margin-bottom:22px}.nodes{display:grid;grid-template-columns:repeat(5,1fr);gap:16px}.node{display:grid;gap:10px;text-align:left;padding:16px;background:#234958;color:#fff;border:1px solid #628391}.node[aria-pressed=true]{background:#e6f3f7;color:#133c4c;border:2px solid #97d7eb}.node[aria-pressed=true] small{color:#315a6a}.node small{color:#c1d6df}.node-code{font:12px monospace}.relationship{display:flex;flex-wrap:wrap;gap:12px 24px;font-size:12px;margin-top:24px;color:#c1d6df}.trace-layout{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin-top:24px}.current h2{margin-top:20px;font-size:30px}#trace{padding-left:25px}#trace li{color:#657782;padding:4px 0}#trace button{padding:8px 10px;min-height:38px;border:0;text-align:left;width:100%;background:transparent}#trace small{display:block}#trace .now{background:var(--soft);color:var(--accent)}#trace .done{color:#21613d}@media(max-width:850px){.nodes{grid-template-columns:repeat(2,1fr)}.node:last-child{grid-column:1/-1}}@media(max-width:720px){.trace-layout{grid-template-columns:1fr}.system{padding:18px}.nodes{gap:10px}.node{padding:12px}.current h2{font-size:25px}}''')

items=[
['html','研究决策简报','scenario-report.html','项目评审者需要从五份已有研究中决定下一步投入。','综合报告：结论先行、证据矩阵、范围筛选、来源下钻与未验证事项。','资料驱动内容；表格保留精确比较；交互回答后续问题；不发明评分。'],
['design-artifact','海岸观察专题','scenario-design.html','面向公众的阅读专题，需要从海岸主题形成明确的视觉方向。','海岸等高线主视觉、宋体标题、章节式阅读、水位示意、深浅主题。','视觉选择来自主题；文字与图像共同组织阅读；交互服务内容。'],
['html-wireframe','客服工作台结构','scenario-wireframe.html','客服主管要决定如何组织队列、工单上下文和下一步处理。','同样三条工单，比较队列详情、优先级看板、逐件处理三种结构。','只比较结构和导航；真实标签与代表内容；保持低保真，暂缓视觉与后端。'],
['html-prototype','内容发布审核','scenario-prototype.html','编辑要完成审核，并验证退回、保存失败、重试与发布门槛。','完整稿件预览、三项检查、审核日志、退回原因弹窗、失败重试和发布边界。','关键流程的状态完整；表单与反馈可信；键盘可操作；真实系统接管点明确。'],
['html-plan','知识库迁移方案','scenario-plan.html','项目负责人要核对迁移顺序、回退准备和切换条件是否忠于委托。','六阶段方案、双前置汇合、交付与门槛、未决事项、逐项来源。','保持承诺可追溯；角色、依赖与未知分开；不虚构日期、进度或通过状态。'],
['html-diagram','异步图片处理','scenario-diagram.html','工程团队需要解释上传成功与处理完成的区别，以及异常如何恢复。','固定系统节点、三条请求路径、事件序列、逐步追踪和组件解释。','先选正确图形语义；关系和标签清楚；失败分支可检查；说明简化边界。']]
